import sys
import heapq

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = {}

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))

        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []

        adj[u].append((v, w))
        adj[v].append((u, w))

    try:
        start = int(next(iterator))
    except StopIteration:
        start = 1

    visited = set()
    pq = []
    total_weight = 0

    heapq.heappush(pq, (0, start))

    while pq and len(visited) < n:
        weight, u = heapq.heappop(pq)

        if u in visited:
            continue

        visited.add(u)
        total_weight += weight

        if u in adj:
            for v, w in adj[u]:
                if v not in visited:
                    heapq.heappush(pq, (w, v))

    print(total_weight)

if __name__ == '__main__':
    solve()
